const GENERATED_ICON_NAME_SET: ReadonlySet<string> = new Set(GENERATED_ICON_NAMES);
const GENERATED_ICON_METADATA_BY_ID = new Map<GeneratedIconName, GeneratedIconMetadata>(
  GENERATED_ICON_METADATA.map((entry) => [entry.id, entry]),
);

export function isGeneratedIconName(value: unknown): value is GeneratedIconName {
  return typeof value === 'string' && GENERATED_ICON_NAME_SET.has(value);
}

export function getGeneratedIconMetadata(name: GeneratedIconName): GeneratedIconMetadata {
  return GENERATED_ICON_METADATA_BY_ID.get(name) as GeneratedIconMetadata;
}
